@layer components {
  :where([data-control-family="drawer"][data-slot="backdrop"], [data-control-family="drawer"][data-slot="content"]) {
    --drawer-backdrop-background: oklch(from var(--foreground) l c h / var(--overlay-opacity));
    --drawer-content-radius: var(--radius-panel);
    --drawer-content-background: var(--background);
    --drawer-content-foreground: var(--foreground);
    --drawer-content-border-color: var(--border);
    --drawer-content-shadow: var(--shadow-modal);
  }
  :where([data-control-family="drawer"][data-slot="backdrop"]) {
    background-color: var(--drawer-backdrop-background);
    backdrop-filter: blur(var(--backdrop-blur-overlay));
  }

  :where(.dark [data-control-family="drawer"][data-slot="backdrop"]) {
    --drawer-backdrop-background: oklch(from var(--background) l c h / var(--overlay-opacity));
  }

  :where([data-control-family="drawer"][data-slot="content"]) {
    --_drawer-content-closed-translate: 0 100%;
    border: 0 solid var(--drawer-content-border-color);
    background-color: var(--drawer-content-background);
    color: var(--drawer-content-foreground);
    box-shadow: var(--drawer-content-shadow);
  }

  :where([data-control-family="drawer"][data-slot="content"][data-surface-variant="card"]) {
    --drawer-content-background: var(--card);
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="floating"]) {
    border-width: 1px;
    border-radius: var(--drawer-content-radius);
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="edge"][data-side="bottom"]) {
    border-top-width: 1px;
    border-radius: var(--drawer-content-radius) var(--drawer-content-radius) 0 0;
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="edge"][data-side="top"]) {
    border-bottom-width: 1px;
    --_drawer-content-closed-translate: 0 -100%;
    border-radius: 0 0 var(--drawer-content-radius) var(--drawer-content-radius);
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="edge"][data-side="right"]) {
    border-left-width: 1px;
    --_drawer-content-closed-translate: 100% 0;
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="edge"][data-side="left"]) {
    border-right-width: 1px;
    --_drawer-content-closed-translate: -100% 0;
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="floating"][data-side="bottom"]) {
    --_drawer-content-closed-translate: 0 calc(100% + var(--_drawer-float-gap));
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="floating"][data-side="top"]) {
    --_drawer-content-closed-translate: 0 calc(-100% - var(--_drawer-float-gap));
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="floating"][data-side="right"]) {
    --_drawer-content-closed-translate: calc(100% + var(--_drawer-float-gap)) 0;
  }

  :where([data-control-family="drawer"][data-slot="content"][data-variant="floating"][data-side="left"]) {
    --_drawer-content-closed-translate: calc(-100% - var(--_drawer-float-gap)) 0;
  }

  :where([data-control-family="drawer"][data-slot="handle"]) {
    border-radius: 9999px;
    background-color: oklch(from var(--muted-foreground) l c h / 0.3);
  }

  :where([data-control-family="drawer"][data-slot="title"]) {
    color: var(--foreground);
    font-weight: 600;
  }

  :where([data-control-family="drawer"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-sm);
  }

  :where([data-control-family="drawer"][data-slot="header"]) {
    --_drawer-header-text-align: center;
    text-align: var(--_drawer-header-text-align);
  }

  @media (width >= 40rem) {
    :where([data-control-family="drawer"][data-slot="header"]) {
      --_drawer-header-text-align: left;
      text-align: var(--_drawer-header-text-align);
    }
  }

  :where([data-control-family="drawer"][data-slot="content"]) {
    --_drawer-content-outline: none;
    outline-style: var(--_drawer-content-outline);
    transform: translate(var(--drawer-swipe-movement-x, 0), var(--drawer-swipe-movement-y, 0));
    --_drawer-content-transition-property: transform, translate, scale, rotate;
    transition-property: var(--_drawer-content-transition-property);
    --_drawer-content-transition-duration: var(--duration-base);
    transition-duration: var(--_drawer-content-transition-duration);
    transition-timing-function: var(--ease-emphasized);
  }

  :where(
  [data-control-family="drawer"][data-slot="content"][data-starting-style],
  [data-control-family="drawer"][data-slot="content"][data-ending-style]
) {
    translate: var(--_drawer-content-closed-translate);
  }

  :where([data-control-family="drawer"][data-slot="content"][data-swiping]) {
    --_drawer-content-transition-duration: 0ms;
    transition-duration: var(--_drawer-content-transition-duration);
  }

  :where([data-control-family="drawer"][data-slot="backdrop"]) {
    --_drawer-backdrop-transition-property: opacity;
    transition-property: var(--_drawer-backdrop-transition-property);
    transition-timing-function: var(--ease-standard);
    --_drawer-backdrop-transition-duration: var(--duration-base);
    transition-duration: var(--_drawer-backdrop-transition-duration);
  }

  :where([data-control-family="drawer"][data-slot="backdrop"][data-swiping]) {
    --_drawer-backdrop-transition-duration: 0ms;
    transition-duration: var(--_drawer-backdrop-transition-duration);
  }

  :where([data-control-family="drawer"][data-slot="backdrop"][data-ending-style]) {
    --_drawer-backdrop-opacity: 0%;
    opacity: var(--_drawer-backdrop-opacity);
  }

  :where([data-control-family="drawer"][data-slot="backdrop"][data-starting-style]) {
    --_drawer-backdrop-opacity: 0%;
    opacity: var(--_drawer-backdrop-opacity);
  }
}

@property --drawer-backdrop-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --drawer-content-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --drawer-content-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --drawer-content-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --drawer-content-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --drawer-content-shadow {
  syntax: "*";
  inherits: true;
}

"use client";

import { Drawer as DrawerPrimitive } from "@base-ui/react/drawer";
import type { ComponentProps, CSSProperties } from "react";
import type { DrawerContentPadding, DrawerContentSurface, DrawerContentVariant, DrawerSide } from "@/components/control-ui/contracts";
import type { DrawerKnobStyle } from "@/components/control-ui/knob-contracts";
import { cn } from "@/components/control-ui/lib/cn";
import { skinEffects, skinId } from "@/components/control-ui/skin";

// Base UI Drawer throughout — native swipe gestures and snap points, no vaul.

// swipeDirection is dismiss axis — always edge drawer is pinned to
const swipeFor: Record<DrawerSide, ComponentProps<typeof DrawerPrimitive.Root>["swipeDirection"]> = {
  bottom: "down",
  top: "up",
  right: "right",
  left: "left",
};

const placement: Record<DrawerContentVariant, Record<DrawerSide, { viewport: string; popup: string }>> = {
  edge: {
    bottom: {
      viewport: "items-end justify-center",
      popup: "w-full max-h-[85vh]",
    },
    top: {
      viewport: "items-start justify-center",
      popup: "w-full max-h-[85vh]",
    },
    right: {
      viewport: "items-stretch justify-end",
      popup: "h-full w-3/4 max-w-sm",
    },
    left: {
      viewport: "items-stretch justify-start",
      popup: "h-full w-3/4 max-w-sm",
    },
  },
  floating: {
    bottom: {
      viewport:
        "items-end justify-center p-2 pb-[var(--_drawer-float-gap)] [--_drawer-float-gap:max(--spacing(2),env(safe-area-inset-bottom))]",
      popup: "w-full max-h-[85vh]",
    },
    top: {
      viewport:
        "items-start justify-center p-2 pt-[var(--_drawer-float-gap)] [--_drawer-float-gap:max(--spacing(2),env(safe-area-inset-top))]",
      popup: "w-full max-h-[85vh]",
    },
    right: {
      viewport:
        "items-stretch justify-end p-2 pr-[var(--_drawer-float-gap)] [--_drawer-float-gap:max(--spacing(2),env(safe-area-inset-right))]",
      popup: "w-3/4 max-w-sm",
    },
    left: {
      viewport:
        "items-stretch justify-start p-2 pl-[var(--_drawer-float-gap)] [--_drawer-float-gap:max(--spacing(2),env(safe-area-inset-left))]",
      popup: "w-3/4 max-w-sm",
    },
  },
};

// inset belongs to handle, not popup padding — under padding="none" pill would otherwise sit flush against rounded edge
const handleGap: Record<"bottom" | "top", string> = {
  bottom: "mt-2.5 mb-1",
  top: "order-last mt-1 mb-2.5",
};

// skips grabbed edge, whose inset handleGap already owns
const contentPadding: Record<DrawerSide, string> = {
  bottom: "pb-4",
  top: "pt-4",
  right: "py-4",
  left: "py-4",
};

export function Drawer(props: ComponentProps<typeof DrawerPrimitive.Root> & { side?: DrawerSide }) {
  const { side = "bottom", swipeDirection, ...rest } = props;
  return <DrawerPrimitive.Root swipeDirection={swipeDirection ?? swipeFor[side]} {...rest} />;
}

export function DrawerTrigger({
  className,
  ...props
}: ComponentProps<typeof DrawerPrimitive.Trigger> & { style?: CSSProperties & DrawerKnobStyle }) {
  return (
    <DrawerPrimitive.Trigger data-control-ui="drawer" data-control-family="drawer" data-slot="trigger" className={className} {...props} />
  );
}

export function DrawerClose({
  className,
  ...props
}: ComponentProps<typeof DrawerPrimitive.Close> & { style?: CSSProperties & DrawerKnobStyle }) {
  return <DrawerPrimitive.Close data-control-ui="drawer" data-control-family="drawer" data-slot="close" className={className} {...props} />;
}

export function DrawerContent({
  className,
  children,
  side = "bottom",
  padding = "default",
  surface = "background",
  variant = "edge",
  style,
  ...props
}: Omit<ComponentProps<typeof DrawerPrimitive.Popup>, "style"> & {
  side?: DrawerSide;
  padding?: DrawerContentPadding;
  surface?: DrawerContentSurface;
  variant?: DrawerContentVariant;
  style?: CSSProperties & DrawerKnobStyle;
}) {
  const place = placement[variant][side];
  const grabbable = side === "bottom" || side === "top";
  const backdropStyle: (CSSProperties & DrawerKnobStyle) | undefined = style
    ? {
        "--drawer-backdrop-background": style["--drawer-backdrop-background"],
      }
    : undefined;
  return (
    <DrawerPrimitive.Portal>
      {/* portal escapes every token-scoped ancestor, so scope is re-asserted here */}
      <DrawerPrimitive.Backdrop
        data-control-ui="drawer"
        data-control-family="drawer"
        data-slot="backdrop"
        data-skin={skinId()}
        data-effects={skinEffects()}
        className="fixed inset-0 z-[70]"
        style={backdropStyle}
      />
      <DrawerPrimitive.Viewport
        data-control-ui="drawer"
        data-control-family="drawer"
        data-slot="viewport"
        data-skin={skinId()}
        data-effects={skinEffects()}
        className={cn("fixed inset-0 z-[71] flex", place.viewport)}
      >
        <DrawerPrimitive.Popup
          data-control-ui="drawer"
          data-control-family="drawer"
          data-slot="content"
          data-side={side}
          data-surface="modal"
          data-padding={padding}
          data-surface-variant={surface}
          data-variant={variant}
          className={cn("flex flex-col gap-4", padding === "default" && contentPadding[side], place.popup, className)}
          style={style}
          {...props}
        >
          {grabbable ? (
            <div
              data-control-ui="drawer"
              data-control-family="drawer"
              data-slot="handle"
              className={cn("mx-auto h-1.5 w-12 shrink-0", handleGap[side])}
            />
          ) : null}
          <DrawerPrimitive.Content className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto">{children}</DrawerPrimitive.Content>
        </DrawerPrimitive.Popup>
      </DrawerPrimitive.Viewport>
    </DrawerPrimitive.Portal>
  );
}

export function DrawerHeader({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & DrawerKnobStyle }) {
  return (
    <div
      data-control-ui="drawer"
      data-control-family="drawer"
      data-slot="header"
      className={cn("flex flex-col gap-1.5 px-4", className)}
      {...props}
    />
  );
}

export function DrawerFooter({ className, ...props }: ComponentProps<"div"> & { style?: CSSProperties & DrawerKnobStyle }) {
  return (
    <div
      data-control-ui="drawer"
      data-control-family="drawer"
      data-slot="footer"
      className={cn("mt-auto flex flex-col gap-2 px-4", className)}
      {...props}
    />
  );
}

export function DrawerTitle({
  className,
  ...props
}: Omit<ComponentProps<typeof DrawerPrimitive.Title>, "style"> & {
  style?: CSSProperties & DrawerKnobStyle;
}) {
  return <DrawerPrimitive.Title data-control-ui="drawer" data-control-family="drawer" data-slot="title" className={className} {...props} />;
}

export function DrawerDescription({
  className,
  ...props
}: Omit<ComponentProps<typeof DrawerPrimitive.Description>, "style"> & {
  style?: CSSProperties & DrawerKnobStyle;
}) {
  return (
    <DrawerPrimitive.Description
      data-control-ui="drawer"
      data-control-family="drawer"
      data-slot="description"
      className={className}
      {...props}
    />
  );
}
